let firSerial = 0;
function firNo(
  prefix: string,
  stateId: number,
  districtId: number | null,
  unitId: number,
) {
  firSerial += 1;
  return (
    prefix +
    String(stateId).padStart(2, "0") +
    String(districtId ?? 0).padStart(3, "0") +
    String(unitId).padStart(4, "0") +
    "2026" +
    String(firSerial).padStart(5, "0")
  );
}

const pad3 = (n: number) => String(n).padStart(3, "0");
const d = (y: number, m: number, day: number) =>
  new Date(Date.UTC(y, m - 1, day));

function kgid(n: number) {
  return String(100000000000 + n * 9877);
}

const badgePrefixes = [
  "MH",
  "DL",
  "KA",
  "TS",
  "TN",
  "UP",
  "RJ",
  "GJ",
  "BR",
  "WB",
  "PB",
  "CH",
  "MP",
  "KL",
  "HR",
  "CG",
  "JH",
  "AS",
  "UK",
];
function badgeFor(n: number) {
  return `${badgePrefixes[n % badgePrefixes.length]}-${String(10000 + n).padStart(5, "0")}`;
}

function fakeHash(seed: number) {
  const chars = "0123456789abcdef";
  let out = "";
  let x = seed * 2654435761 + 12345;
  for (let i = 0; i < 64; i++) {
    x = (x * 1103515245 + 12345) % 2147483648;
    out += chars[x % 16];
  }
  return out;
}

