async function main() {
  for (const s of states) {
    await prisma.state.create({ data: s });
  }
  for (const drow of districts) {
    await prisma.district.create({ data: drow });
  }
  for (const ut of unitTypes) {
    await prisma.unitType.create({ data: ut });
  }
  for (const pu of policeUnits) {
    await prisma.policeUnit.create({ data: pu });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.POLICE_UNIT,
        entityId: String(pu.id),
        vectorId: `vec-unit-${pu.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(pu.id + 1000),
        metadata: { unitName: pu.unitName },
      },
    });
  }
  for (const r of ranks) {
    await prisma.rank.create({ data: r });
  }
  for (const des of designations) {
    await prisma.designation.create({ data: des });
  }
  for (const emp of employees) {
    await prisma.employee.create({ data: emp });
  }
  for (const g of gravityOffences) {
    await prisma.gravityOffence.create({ data: g });
  }
  for (const ch of crimeHeads) {
    await prisma.crimeHead.create({ data: ch });
  }
  for (const csh of crimeSubHeads) {
    await prisma.crimeSubHead.create({ data: csh });
  }
  for (const a of acts) {
    await prisma.act.create({ data: a });
  }
  for (const s of sections) {
    await prisma.section.create({ data: s });
  }
  for (const m of crimeHeadActSections) {
    await prisma.crimeHeadActSection.create({ data: m });
  }
  for (const cc of caseCategories) {
    await prisma.caseCategory.create({ data: cc });
  }
  for (const cs of caseStatuses) {
    await prisma.caseStatusMaster.create({ data: cs });
  }
  for (const c of courts) {
    await prisma.court.create({ data: c });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.COURT,
        entityId: String(c.id),
        vectorId: `vec-court-${c.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(c.id + 2000),
        metadata: { courtName: c.courtName },
      },
    });
  }
  for (const o of occupations) {
    await prisma.occupationMaster.create({ data: o });
  }
  for (const rel of religions) {
    await prisma.religionMaster.create({ data: rel });
  }
  for (const c of castes) {
    await prisma.casteMaster.create({ data: c });
  }
  for (const mo of modusOperandi) {
    await prisma.modusOperandi.create({ data: mo });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.MODUS_OPERANDI,
        entityId: mo.id,
        modusOperandiId: mo.id,
        vectorId: `vec-mo-${mo.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(3000),
        metadata: { name: mo.name, patterns: mo.patterns },
      },
    });
  }
  for (const org of organizations) {
    await prisma.organization.create({ data: org });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.ORGANIZATION,
        entityId: org.id,
        organizationId: org.id,
        vectorId: `vec-org-${org.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(4000),
        metadata: { name: org.name },
      },
    });
  }
  for (const p of persons) {
    await prisma.person.create({ data: p });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.PERSON,
        entityId: p.id,
        personId: p.id,
        vectorId: `vec-person-${p.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(5000),
        metadata: { name: p.name },
      },
    });
  }
  for (const ph of phones) {
    await prisma.phone.create({ data: ph });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.PHONE,
        entityId: ph.id,
        phoneId: ph.id,
        vectorId: `vec-phone-${ph.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(6000),
        metadata: { number: ph.number },
      },
    });
  }
  for (const po of phoneOwners) {
    await prisma.phoneOwner.create({ data: po });
  }
  for (const v of vehicles) {
    await prisma.vehicle.create({ data: v });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.VEHICLE,
        entityId: v.id,
        vehicleId: v.id,
        vectorId: `vec-vehicle-${v.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(7000),
        metadata: {
          registrationNo: v.registrationNo,
          make: v.make,
          model: v.model,
        },
      },
    });
  }
  for (const vo of vehicleOwners) {
    await prisma.vehicleOwner.create({ data: vo });
  }
  for (const loc of locations) {
    await prisma.location.create({ data: loc });
    await prisma.embedding.create({
      data: {
        entityType: EntityType.LOCATION,
        entityId: loc.id,
        locationId: loc.id,
        vectorId: `vec-location-${loc.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(8000),
        metadata: { address: loc.address },
      },
    });
  }
  for (const pl of personLocations) {
    await prisma.personLocation.create({ data: pl });
  }
  for (const om of organizationMembers) {
    await prisma.organizationMember.create({ data: om });
  }

  for (const c of cases) {
    await prisma.case.create({
      data: {
        id: c.id,
        caseNumber: c.caseNumber,
        crimeNo: c.crimeNo,
        caseNo: c.caseNo,
        title: c.title,
        description: c.description,
        crimeRegisteredDate: c.crimeRegisteredDate,
        incidentFromDate: c.incidentFromDate,
        incidentToDate: c.incidentToDate,
        infoReceivedPSDate: c.infoReceivedPSDate,
        caseCategoryId: c.caseCategoryId,
        gravityOffenceId: c.gravityOffenceId,
        crimeMajorHeadId: c.crimeMajorHeadId,
        crimeMinorHeadId: c.crimeMinorHeadId,
        caseStatusId: c.caseStatusId,
        registeringOfficerId: c.registeringOfficerId,
        policeUnitId: c.policeUnitId,
        courtId: c.courtId,
        riskScore: c.riskScore,
        priorityScore: c.priorityScore,
        aiSummary: c.aiSummary,
        aiClassification: c.aiClassification,
        modusOperandiId: c.modusOperandiId,
        complainants: { create: c.complainants },
        persons: { create: c.persons },
        actSections: { create: c.actSections },
        vehicles: { create: c.vehicles },
        phones: { create: c.phones },
        locations: { create: c.locations },
        organizations: { create: c.organizations },
      },
    });

    await prisma.embedding.create({
      data: {
        entityType: EntityType.CASE,
        entityId: c.id,
        caseId: c.id,
        vectorId: `vec-case-${c.id}`,
        modelName: "text-embedding-3-small",
        contentHash: fakeHash(9000),
        metadata: { caseNumber: c.caseNumber, title: c.title },
      },
    });

    const evIds: string[] = [];
    for (let i = 0; i < c.evidence.length; i++) {
      const ev = c.evidence[i];
      const created = await prisma.evidence.create({
        data: {
          caseId: c.id,
          type: ev.type,
          title: ev.title,
          description: ev.description,
          fileUrl: `https://storage.example.gov.in/evidence/${c.id}/${ev.fileName}`,
          mimeType: ev.mimeType,
          fileName: ev.fileName,
          fileSize: ev.fileSize,
          fileHash: fakeHash(10000 + i),
          uploadedById: ev.uploadedById,
          extractedData: ev.extractedData,
          aiSummary: ev.aiSummary,
          aiClassification: ev.aiClassification,
          aiConfidence: ev.aiConfidence,
          processedAt: ev.processedAt,
        },
      });
      evIds.push(created.id);
      await prisma.embedding.create({
        data: {
          entityType: EntityType.EVIDENCE,
          entityId: created.id,
          caseId: c.id,
          evidenceId: created.id,
          vectorId: `vec-evidence-${c.id}-${i}`,
          modelName: "text-embedding-3-small",
          contentHash: fakeHash(11000 + i),
          metadata: { title: ev.title, type: ev.type },
        },
      });
    }

    const arIds: string[] = [];
    for (let i = 0; i < c.arrests.length; i++) {
      const ar = c.arrests[i];
      const created = await prisma.arrestSurrender.create({
        data: {
          id: `ARS-${c.id}-${i + 1}`,
          caseId: c.id,
          type: ar.type,
          eventDate: ar.eventDate,
          stateId: ar.stateId,
          districtId: ar.districtId,
          policeUnitId: ar.policeUnitId,
          ioId: ar.ioId,
          courtId: ar.courtId,
          isAccused: true,
          isComplainantAccused: false,
          accused: {
            create: ar.accused.map((pid, idx) => ({
              personId: pid,
              accusedSortId: `A${idx + 1}`,
              isPrimary: idx === 0,
            })),
          },
        },
      });
      arIds.push(created.id);
    }

    for (let i = 0; i < c.chargesheets.length; i++) {
      const cs = c.chargesheets[i];
      await prisma.chargesheet.create({
        data: {
          id: `CSH-${c.id}-${i + 1}`,
          caseId: c.id,
          csDate: cs.csDate,
          csType: cs.csType,
          policePersonId: cs.policePersonId,
        },
      });
    }

    for (let i = 0; i < c.faceRecords.length; i++) {
      const fr = c.faceRecords[i];
      const evidenceId =
        fr.evidenceIdx != null && evIds[fr.evidenceIdx]
          ? evIds[fr.evidenceIdx]
          : null;
      await prisma.faceRecord.create({
        data: {
          personId: fr.personId,
          caseId: c.id,
          evidenceId,
          luxandSubjectId: `LUX-${c.id}-${fr.personId}`,
          luxandFaceId: `LUXFACE-${c.id}-${i}`,
          imageKey: `faces/${c.id}/${fr.personId}.jpg`,
          imageUrl: `https://storage.example.gov.in/faces/${c.id}/${fr.personId}.jpg`,
          confidence: fr.confidence,
          metadata: { capturedAt: c.crimeRegisteredDate.toISOString() },
        },
      });
    }

    for (let i = 0; i < c.events.length; i++) {
      const ev = c.events[i];
      await prisma.investigationEvent.create({
        data: {
          id: `IEV-${c.id}-${i + 1}`,
          caseId: c.id,
          eventType: ev.eventType,
          eventDate: ev.eventDate,
          officerId: ev.officerId,
          personId: ev.personId,
          evidenceId: ev.evidenceIdx != null ? evIds[ev.evidenceIdx] : null,
          arrestSurrenderId: ev.arrestIdx != null ? arIds[ev.arrestIdx] : null,
          locationId: ev.locationId,
          description: ev.description,
          metadata: ev.metadata,
        },
      });
    }
  }

  for (const rel of personRelationships) {
    await prisma.personRelationship.create({ data: rel });
  }

  for (const sim of caseSimilarities) {
    await prisma.caseSimilarity.create({ data: sim });
  }
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
